/** The checkout after a confirmed code, and the credential that acts for the customer with the confirmed email. */ export type CheckoutCustomerVerificationConfirmation = { /** The new checkout credential, the only one that acts for the customer. Send checkout_auth_token as X-Checkout-Session-Secret on every later checkout request. The earlier credential keeps working for the checkout without the customer's saved cards or details. Omitted for purpose confirm_saved_payment_method, which keeps the checkout's credential. */ "checkout_access"?: { "checkout_auth_token": string; "hosted_url"?: string; }; /** The checkout session, read as its new credential reads it: it acts for the customer with the confirmed email. */ "checkout_session": { "active_payment_attempt"?: { /** RFC3339 timestamp. Format: date-time. */ "completed_at"?: string; "expected_outstanding_money": MoneyValue; /** Reason code for an attempt failure or interrupted payment step, when available. For payment declines, inspect each payment leg's last_payment_error.code. Unmapped values are returned as attempt_failed. */ "failure_code"?: "card_declined" | "insufficient_funds" | "bank_account_closed" | "bank_account_not_found" | "bank_debit_not_authorized" | "bank_account_restricted" | "bank_debit_limit_exceeded" | "authentication_required" | "payment_blocked" | "expired_card" | "incorrect_cvc" | "processing_error" | "payment_method_unavailable" | "payment_method_declined" | "payment_not_completed" | "payment_action_expired" | "payment_method_temporarily_unavailable" | "payment_failed" | "authorization_canceled" | "coupon_reservation_failed" | "invalid_payment_source" | "inventory_unavailable" | "order_changed_before_payment" | "order_payment_customer_mismatch" | "payment_attempt_canceled" | "payment_attempt_expired" | "payment_authorization_canceled" | "payment_authorization_expired" | "payment_confirmation_rejected" | "payment_confirm_outcome_unknown" | "payment_link_capacity_claim_failed" | "payment_link_capacity_validation_failed" | "payment_method_activation_pending" | "payment_method_required" | "payment_option_not_allowed" | "payment_option_unavailable" | "payment_source_binding_failed" | "payment_source_conflict" | "payment_source_not_updatable" | "payment_source_ownership_mismatch" | "receipt_email_failed" | "resource_guarantee_failed" | "setup_action_unavailable" | "setup_canceled" | "setup_cancellation_outcome_unknown" | "setup_cancellation_pending" | "setup_confirmation_outcome_unknown" | "setup_hold_acquisition_failed" | "setup_preparation_outcome_unknown" | "setup_processing" | "setup_result_incomplete" | "setup_status_unknown" | "tip_allocation_sync_failed" | "zero_balance_hold_acquisition_failed" | "attempt_failed" | (string & {}); /** Explanation of an attempt failure or interrupted payment step, when available. For payment declines, inspect each payment leg's last_payment_error.message. */ "failure_message"?: string; /** Whether the attempt can continue through PayOrder with action: resume and this payment_attempt_id after any pending client action is complete. If false, check status before starting another payment; the attempt may still be in progress. */ "is_resumable": boolean; "mode": "payment" | "setup" | "settlement" | (string & {}); "payment_attempt_id": string; "payment_intents"?: Array<PaymentAttemptPaymentIntent>; "pending_actions"?: Array<PendingPaymentAction>; /** RFC3339 timestamp. Format: date-time. */ "started_at"?: string; "status": "processing" | "requires_action" | "requires_capture" | "partially_succeeded" | "requires_retry" | "finalizing" | "succeeded" | "failed" | "expired" | "canceled" | (string & {}); }; /** Contact the buyer entered in checkout before paying, saved with the session's checkout credential. Omitted until the buyer saves one. When a checkout session payment omits buyer_email or buyer_phone, Flint uses these values. Flint clears the contact 30 days after the session ends, and when a customer linked to the session is deleted. */ "buyer_contact"?: { /** Email the buyer entered, exactly as typed. Null when the buyer has not entered an email or cleared it. Format: email. maxLength: 255. */ "email": string | null; /** Phone the buyer entered, in E.164 format. Null when the buyer has not entered a phone or cleared it. pattern: ^\+[1-9][0-9]{1,14}$. */ "phone": string | null; /** When the buyer last changed the saved contact. Format: date-time. */ "updated_at": string; }; "checkout_session_id": string; /** Internal reason supplied when the checkout session was closed. This is not shown to the buyer. */ "closed_reason"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "custom_text"?: CheckoutCustomTextWriteConfig; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_collection"?: CheckoutCustomerConfig; /** Contact and default addresses of the customer the checkout acts for: the customer the merchant created the session for, or the customer whose email the buyer confirmed in it. Present only on reads with the session's checkout credential while the session is open and acts for a customer. */ "customer_prefill"?: { /** The customer's default billing address. Omitted when the customer has none. */ "billing_address"?: { "city": string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country": string; "line1": string; "line2"?: string; "postal_code": string; "state": string; }; /** The customer's email. */ "email": string; /** The customer's default shipping address. Omitted when the customer has none. */ "shipping_address"?: { "city": string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country": string; "line1": string; "line2"?: string; "postal_code": string; "state": string; }; }; /** Immutable delivery method assignment captured when the checkout was created. */ "delivery_method_ids": Array<string>; /** Merchant-only immutable configuration lineage used to evaluate delivery quotes. */ "delivery_pinned_dependencies"?: Array<CheckoutDeliveryPinnedDependency>; /** Whether the order has at least one remaining quote-resolved fulfillment choice that must be selected before payment. */ "delivery_selection_required": boolean; "expiration"?: CheckoutExpirationConfig; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Current fulfillment choices for Flint-owned pricing. Checkout credentials receive the fields available to buyers; merchant credentials also receive configuration lineage and diagnostics. External pricing reports requires_explicit_quote; reading this field does not request a delivery quote. Omitted when the session is not open, has no order, or Flint cannot read its delivery. */ "fulfillment"?: (({ "choice_groups": Array<DeliveryQuoteChoiceGroupResource>; "delivery_quote_id"?: string; "evaluation_status": "complete" | "incomplete" | "degraded" | "requires_explicit_quote" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Inputs the checkout's delivery methods need. Once the checkout has a delivery quote, these are the quote's input_requirements. Before that, they come from the methods alone and name no choice group: the fields in each method's quote_input_fields, and each recipient field a method requires. */ "input_requirements": Array<DeliveryInputRequirement>; "merchant_diagnostics": Array<DeliveryMerchantDiagnostic>; }) | ({ "buyer_reasons": Array<string>; "choice_groups": Array<BuyerDeliveryQuoteChoiceGroupResource>; "delivery_quote_id"?: string; "evaluation_status": "complete" | "incomplete" | "degraded" | "requires_explicit_quote" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Inputs the checkout's delivery methods need. Once the checkout has a delivery quote, these are the quote's input_requirements. Before that, they come from the methods alone and name no choice group: the fields in each method's quote_input_fields, and each recipient field a method requires. */ "input_requirements": Array<BuyerDeliveryInputRequirementResource>; }) | (object)); "invoice"?: (({ "collection_block_status"?: "none" | "inventory_blocked" | "resolved" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "due_at"?: string; "invoice_id": string; "invoice_number"?: string; "is_overdue": boolean; "order_id"?: string; "outstanding_money": MoneyValue; "paid_money": MoneyValue; "refund_status"?: "none" | "partially_refunded" | "refunded" | (string & {}); "refunded_money": MoneyValue; "status": "draft" | "open" | "partially_paid" | "paid" | "void" | "uncollectible" | "credited" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "invoice_id"?: string; "legal"?: LegalSettings; "merchant_id"?: string; /** How the buyer can reach the merchant for help: the support email, phone, and URL the merchant set. Present only on reads with the session's checkout credential, and only when the merchant set at least one of them. Show it where your checkout tells the buyer to contact the merchant, such as an expired or closed checkout, or your receipt. */ "merchant_support"?: { /** Support email address. Format: email. */ "email"?: string; /** Support phone number. */ "phone"?: string; /** Support page, as an absolute http or https URL. Format: uri. */ "url"?: string; }; "metadata"?: Record<string, string>; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "settlement_amounts": SettlementAmounts; "status": "open" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "order_id"?: string; "origin"?: "virtual_terminal" | "payment_link" | "checkout" | "api" | "subscription" | (string & {}); "payment_collection"?: { "stripe"?: PaymentCollectionStripe; }; "payment_intent_ids"?: Array<string>; "payment_intents"?: Array<ExpandedPaymentIntentSummary>; "payment_link"?: (({ /** Format: int32. */ "completed_count": number; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "description"?: string; "name": string; "payment_link_id": string; "payment_link_type"?: "standard" | "donation" | "event" | (string & {}); "plan_id"?: string; "status": "active" | "inactive" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; "url"?: string; }) | (null)); "payment_link_id"?: string; /** The card the buyer saved with this checkout's payment by giving a mobile phone number, and whether they confirmed it. Present only on reads with the session's checkout credential, after a payment that paid the order in full, or that was approved for the merchant to capture later, and saved a card this way. A checkout whose payment is approved stays open until the capture. */ "payment_method_save"?: { /** True while status is pending after the buyer confirmed the number by text, when the number alone can't save the card: the customer with the buyer's email existed before this payment, the buyer did not confirm that email in this checkout, and the number isn't already the customer's saved number with an active card saved with it. The buyer confirms the email with an emailed code to finish; the card is then saved with the number, which replaces the customer's saved number. */ "email_confirmation_required": boolean; /** When a pending save stops waiting: 24 hours after the payment succeeded or was approved. Format: date-time. */ "expires_at"?: string | null; /** Last two digits of the number the buyer gave, which a code is texted to. Set while status is pending. */ "phone_last_digits"?: string; "saved_with"?: "sms" | "email" | (string & {}); "status": "pending" | "saved" | "expired" | (string & {}); }; "payments"?: CheckoutPaymentConfig; "plan_id"?: string; /** Named conditions that affect checkout completion. Follow each problem's remediation action instead of reconstructing delivery lifecycle rules in the client. When Flint cannot read the checkout's delivery, the read still succeeds and reports delivery_selection_stale; its remediation says whether reading the session again can succeed, and its next action's reason_code names the error. */ "problems": Array<CheckoutProblemResource>; "promotion_config"?: CheckoutPromotionConfig; /** RFC3339 deadline for the restricted payment-attempt recovery window. Format: date-time. */ "recovery_expires_at"?: string | null; /** Whether this terminal session credential is temporarily restricted to recovering its owning payment attempt. */ "recovery_mode": boolean; /** Payment attempt that this checkout credential may recover while recovery_mode is true. */ "recovery_payment_attempt_id"?: string; "redirects"?: CheckoutRedirectsConfig; /** Whether checkout offers the buyer the option to save the card they type for faster checkout at this merchant. Present only on reads with the session's checkout credential. When true and save_payment_method_requires_verification is false, PayOrder accepts save_payment_method: true for one newly collected card. False when the merchant turned checkout.saved_payment_details off, customer accounts are merchant hosted, card is not an available payment option, the checkout collects an invoice, a subscription, or a return, or the checkout acts for no customer and Flint cannot email the buyer a verification code. */ "save_payment_method_offered"?: boolean; /** Whether the buyer can save the card they type by giving a US or Canadian mobile phone number with the payment, in save_payment_method_phone on POST /v1/orders/{order_id}/pay, and confirming it with a texted code after paying. Present only on reads with the session's checkout credential. True while Flint can send texts and either save_payment_method_requires_verification is true, so the number replaces confirming an email before paying, or the checkout acts for the customer whose email the buyer confirmed with this credential, so the number joins that customer's saved details once the buyer confirms it. */ "save_payment_method_phone_offered"?: boolean; /** Whether the buyer must confirm their email with a code before the checkout can save their card or use their saved cards. Present only on reads with the session's checkout credential. True when save_payment_method_offered is true and the checkout acts for no customer for this credential: the merchant created it without one, and either the buyer has not confirmed an email with this credential, or the customer whose email they confirmed has since changed that email or been deleted. A credential other than the one a confirmation returned, such as the hosted checkout link opened on another device, reads true. Send the code with POST /v1/checkout-sessions/{checkout_session_id}/customer-verifications. False while the checkout acts for a customer, and whenever save_payment_method_offered is false. */ "save_payment_method_requires_verification"?: boolean; "setup_collection"?: { "stripe"?: PaymentCollectionStripe; }; "status": "open" | "paid" | "partially_paid" | "expired" | "closed" | "invalidated" | (string & {}); /** Renewal terms a subscription checkout commits the buyer to. Frozen when the session's order was created, so later plan changes do not alter them. Absent when the checkout starts no subscription. */ "subscription_terms"?: { "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Number of billing intervals between recurring charges. Format: int32. */ "billing_interval_count": number; /** Minimum commitment in months, when the plan has one. Format: int32. */ "contract_term_months"?: number; /** Fee charged when the buyer cancels before the contract term ends, when the plan has one. */ "early_termination_fee_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Flint subscription plan ID the terms come from. */ "plan_id": string; /** Plan name shown to the buyer. */ "plan_name": string; /** Charge for one billing interval before tax: each line's unit price times its quantity, plus modifiers. */ "recurring_total_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** One-time fee charged with the first payment, when the plan has one. */ "setup_fee_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Days before the first recurring charge, when the plan has a trial. Format: int32. */ "trial_period_days"?: number; }; "superseding_checkout_session_id"?: string; "surface": "hosted" | "embedded" | (string & {}); "tax"?: CheckoutTaxConfig; "terminal_reason"?: "payment_succeeded" | "payment_partially_succeeded" | "expired" | "api" | "order_mutated" | "superseded" | "invoice_paid_elsewhere" | "invoice_voided" | "invoice_uncollectible" | "invoice_balance_changed" | (string & {}); "theme"?: ThemeConfig; "tip"?: CheckoutTipConfig; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; "url"?: string; }; };
